insert into public.articles (id, title, slug, excerpt, content, category, subcategory, author_id, published_at, read_time, tags, featured, gradient) values
('e1', 'How to Calculate Your CGPA on the 5.0 Scale (Nigerian Universities)', 'cgpa-5-point-scale-guide',
 'A complete walkthrough of calculating your Cumulative Grade Point Average on the Nigerian 5.0 grading system, with worked examples for every faculty.',
 $j$[{"type":"paragraph","content":"Understanding how to calculate your CGPA is essential for every Nigerian university student. The 5.0 scale is used by most federal and state universities, and the calculation follows a consistent formula."},{"type":"heading","content":"The Grading System"},{"type":"list","content":["A = 5 points (70-100%)","B = 4 points (60-69%)","C = 3 points (50-59%)","D = 2 points (45-49%)","E = 1 point (40-44%)","F = 0 points (Below 40%)"]},{"type":"heading","content":"Step-by-Step Calculation"},{"type":"paragraph","content":"Multiply each course grade point by its unit value to get quality points. Sum all quality points and divide by total units taken. The result is your GPA for that semester."},{"type":"code","content":"GPA = Sum of (Grade Point x Unit) / Total Units

Example:
MTH101: A(5) x 3 units = 15
PHY101: B(4) x 3 units = 12
CHM101: A(5) x 2 units = 10
GST101: B(4) x 2 units = 8

GPA = (15+12+10+8) / (3+3+2+2) = 45/10 = 4.5"},{"type":"callout","content":"CGPA is calculated the same way but across ALL semesters. Add up total quality points from every semester and divide by total units from every semester."},{"type":"paragraph","content":"Most Nigerian universities classify degrees as: First Class (4.50-5.00), Second Class Upper (3.50-4.49), Second Class Lower (2.40-3.49), Third Class (1.50-2.39), Pass (1.00-1.49)."}]$j$::jsonb,
 'education', 'GPA & CGPA Guides', 'a4', '2025-01-14', 10, array['CGPA','5.0 Scale','Nigerian Universities','Grading'], true, 'from-blue-700 to-indigo-600'),
('e2', 'JAMB 2025: Complete Preparation Guide with Past Questions Strategy', 'jamb-2025-preparation-guide',
 'A proven study plan for JAMB UTME preparation covering all four subjects, time management, and how to use past questions effectively.',
 $j$[{"type":"paragraph","content":"JAMB UTME remains the gateway to Nigerian university admission. With over 2 million candidates annually, strategic preparation separates successful candidates from the rest."},{"type":"heading","content":"The 8-Week Study Plan"},{"type":"list","content":["Weeks 1-2: Cover all topics in your four subjects using recommended textbooks","Weeks 3-4: Solve past questions from 2015-2020, one subject per day","Weeks 5-6: Focus on weak areas identified from past question analysis","Weeks 7-8: Full mock CBT exams under timed conditions, daily"]},{"type":"heading","content":"Subject-Specific Tips"},{"type":"paragraph","content":"Mathematics: Practice speed with shortcuts. English: Master comprehension and register/tone questions. Sciences: Focus on definitions and diagrams. Social Sciences: Build a timeline of key events."},{"type":"callout","content":"Critical insight: JAMB repeats concepts, not exact questions. Understanding the underlying principle behind each past question is far more valuable than memorizing answers."},{"type":"paragraph","content":"On exam day, arrive 2 hours early. Read each question twice before answering. Flag uncertain questions and return to them. Never leave a question unanswered, there is no penalty for wrong answers."}]$j$::jsonb,
 'education', 'Examination Preparation', 'a2', '2025-01-12', 14, array['JAMB','UTME','Exam Prep','Nigeria'], true, 'from-green-600 to-emerald-500'),
('e3', 'WAEC Mathematics: 20 Must-Know Formulas and Problem-Solving Techniques', 'waec-mathematics-formulas',
 'The essential formulas every WAEC candidate needs, organized by topic with worked examples showing exactly how examiners expect solutions to be presented.',
 $j$[{"type":"paragraph","content":"WAEC Mathematics rewards both correct answers and proper working. This guide covers the 20 formulas that appear most frequently and shows you how to present your solutions for maximum marks."},{"type":"heading","content":"Algebra & Equations"},{"type":"list","content":["Quadratic formula: x = (-b +/- sqrt(b^2 - 4ac)) / 2a","Remainder theorem: If f(x) is divided by (x-a), remainder = f(a)","Factorization: ab + ac = a(b + c)","Simultaneous equations: Use substitution or elimination"]},{"type":"heading","content":"Geometry & Trigonometry"},{"type":"list","content":["Pythagoras: a^2 + b^2 = c^2","Circle area: pi x r^2, Circumference: 2 x pi x r","Cylinder volume: pi x r^2 x h","SOH-CAH-TOA for right triangle trigonometry"]},{"type":"callout","content":"Examiner tip: Always state the formula before substituting values. Show at least one working step. Even if your final answer is wrong, correct method earns method marks."}]$j$::jsonb,
 'education', 'Examination Preparation', 'a2', '2025-01-09', 11, array['WAEC','Mathematics','Formulas','Exam Prep'], false, 'from-orange-500 to-red-500'),
('e4', 'Scholarships for Nigerian Students: 2025 Complete Directory', 'scholarships-nigerian-students-2025',
 'A curated list of fully-funded and partially-funded scholarships available to Nigerian undergraduate and postgraduate students, with eligibility criteria and application deadlines.',
 $j$[{"type":"paragraph","content":"Nigerian students have access to over 50 international and local scholarships annually. This directory covers the most accessible and well-funded opportunities for 2025."},{"type":"heading","content":"Fully Funded International Scholarships"},{"type":"list","content":["Chevening Scholarship (UK): Full tuition + stipend, deadline November","Commonwealth Scholarships: For Masters/PhD in UK, deadline December","MTN Foundation Scholarship: For Nigerian undergraduates, deadline March","Dangote Foundation Scholarship: STEM-focused, deadline January","Mastercard Foundation: Pan-African, covers full costs, deadline varies"]},{"type":"heading","content":"Application Tips That Work"},{"type":"paragraph","content":"Start preparing documents 3 months before deadlines. Write a compelling personal statement that connects your background to your future goals. Get recommendation letters from professors who know your work personally."},{"type":"callout","content":"Common mistake: Applying to only one scholarship. Successful candidates apply to 5-10 programs simultaneously, tailoring each application to the specific funder priorities."}]$j$::jsonb,
 'education', 'Scholarships', 'a4', '2025-01-07', 9, array['Scholarships','Study Abroad','Funding','Nigeria'], true, 'from-purple-600 to-violet-500'),
('e5', 'Best Online Learning Platforms for African Students (Free & Paid)', 'online-learning-platforms-africa',
 'A comprehensive review of the best e-learning platforms accessible from Nigeria and across Africa, covering course quality, pricing, and mobile experience.',
 $j$[{"type":"paragraph","content":"Online learning has democratized education across Africa. But not all platforms work well with Nigerian internet speeds, payment methods, or curriculum needs. Here is our tested ranking."},{"type":"heading","content":"Free Platforms"},{"type":"list","content":["Khan Academy: Best for math and science foundations, works offline","Coursera Audit Mode: Access course materials free, pay only for certificates","edX Audit Track: Similar to Coursera, great for university-level content","Alison: Free certificates, wide range of vocational courses"]},{"type":"heading","content":"Paid Platforms Worth the Investment"},{"type":"paragraph","content":"Udemy courses go for as low as 10,000 Naira during sales. For professional development, Coursera Plus at $59/month gives unlimited access to 7,000+ courses from top universities."},{"type":"callout","content":"Low-bandwidth tip: Download courses on WiFi and study offline. Khan Academy, Coursera, and Udemy all support offline downloads on mobile."}]$j$::jsonb,
 'education', 'Online Learning', 'a6', '2025-01-04', 8, array['Online Learning','Platforms','Africa','Free Courses'], false, 'from-cyan-500 to-blue-600'),
('e6', 'University Admission Guide: How to Choose the Right Course and School in Nigeria', 'university-admission-guide-nigeria',
 'A practical framework for Nigerian students to evaluate universities, choose courses aligned with career goals, and navigate the admission process successfully.',
 $j$[{"type":"paragraph","content":"Choosing a university and course is one of the most consequential decisions a Nigerian student makes. This guide provides a structured framework to make an informed choice."},{"type":"heading","content":"Evaluating Universities"},{"type":"list","content":["Accreditation: Verify NUC accreditation for the specific program","Employability: Research graduate employment rates and industry partnerships","Facilities: Visit campus if possible, check library, labs, and internet access","Location: Consider cost of living, safety, and proximity to industry hubs","Alumni Network: Strong alumni communities open doors after graduation"]},{"type":"heading","content":"Matching Course to Career"},{"type":"paragraph","content":"Do not choose a course based solely on JAMB subject combination. Research what professionals in that field actually do day-to-day. Talk to at least three people working in roles you aspire to."},{"type":"paragraph","content":"Post-UTME preparation is equally critical. Each university has its own format: some test current affairs, others focus on your chosen field. Start preparing at least 3 weeks before the scheduled date."}]$j$::jsonb,
 'education', 'University Guides', 'a2', '2024-12-30', 10, array['University','Admission','Course Selection','Nigeria'], false, 'from-teal-500 to-green-600'),
('e7', 'Study Techniques Backed by Science: What Actually Works for Exams', 'science-backed-study-techniques',
 'Evidence-based learning strategies including spaced repetition, active recall, and interleaving, adapted for Nigerian university and exam contexts.',
 $j$[{"type":"paragraph","content":"Most students study inefficiently. Re-reading notes and highlighting textbooks feel productive but produce minimal long-term retention. Here are techniques proven by cognitive science research."},{"type":"heading","content":"Active Recall"},{"type":"paragraph","content":"Instead of re-reading, close your book and try to recall information from memory. Use flashcards or write summaries from scratch. This retrieval practice strengthens neural pathways far more than passive review."},{"type":"heading","content":"Spaced Repetition"},{"type":"paragraph","content":"Review material at increasing intervals: 1 day, 3 days, 7 days, 14 days, 30 days. Apps like Anki automate this process. For WAEC or JAMB prep, start spaced repetition at least 8 weeks before the exam."},{"type":"callout","content":"The testing effect: Students who take practice tests retain 50% more information than students who spend the same time re-reading material. Mock exams are not just preparation, they are the most effective study method."}]$j$::jsonb,
 'education', 'Study Resources', 'a6', '2024-12-25', 7, array['Study Tips','Science','Memory','Exams'], false, 'from-indigo-500 to-purple-600'),
('e8', 'Student Productivity: Managing Assignments, Exams, and Side Projects', 'student-productivity-guide',
 'A practical system for Nigerian students to balance academic workload, personal projects, and rest without burning out.',
 $j$[{"type":"paragraph","content":"The combination of demanding coursework, part-time work, and personal projects creates a productivity crisis for many students. This guide offers a realistic system that accounts for Nigerian university schedules."},{"type":"heading","content":"The Weekly Planning Method"},{"type":"list","content":["Sunday evening: Review the week ahead, identify deadlines and exams","Block time for lectures, study sessions, and project work","Set one primary goal per day (not five)","Include buffer time for unexpected delays, power outages, or schedule changes","Friday evening: Review what was completed, adjust next week plan"]},{"type":"heading","content":"Tools That Work Offline"},{"type":"paragraph","content":"Not every productivity tool requires constant internet. Use physical notebooks, local apps, or simple spreadsheets. The best system is the one you actually maintain consistently."}]$j$::jsonb,
 'education', 'Student Productivity', 'a6', '2024-12-18', 6, array['Productivity','Time Management','Students'], false, 'from-lime-500 to-green-600'),
('e9', 'Career Opportunities in Tech for Non-Computer Science Graduates', 'tech-careers-non-cs-graduates',
 'How graduates from any discipline can break into tech careers through targeted skills, portfolio building, and strategic networking in the Nigerian market.',
 $j$[{"type":"paragraph","content":"You do not need a Computer Science degree to build a successful tech career. Some of the best product managers, UX designers, and data analysts come from non-traditional backgrounds."},{"type":"heading","content":"Entry Points into Tech"},{"type":"list","content":["UI/UX Design: Learn Figma, build 3 portfolio projects, apply to agencies","Data Analysis: Master Excel, SQL, and Python basics, target fintech companies","Technical Writing: Strong English + basic coding knowledge = high demand","QA Testing: Learn testing frameworks, get ISTQB certified, join startups","Product Management: Domain expertise + communication skills + tech literacy"]},{"type":"paragraph","content":"The Nigerian tech ecosystem is growing rapidly. Companies like Flutterwave, Paystack, Interswitch, and dozens of startups hire from diverse educational backgrounds. Focus on demonstrating skills, not credentials."}]$j$::jsonb,
 'education', 'Career Opportunities', 'a4', '2024-12-15', 8, array['Career','Tech Jobs','Non-CS','Nigeria'], false, 'from-fuchsia-500 to-pink-600'),
('e10', 'Post-UTME Preparation: How to Score High in University Screening Exams', 'post-utme-preparation-guide',
 'A comprehensive strategy for preparing for Post-UTME screening exams, covering common question patterns, subject-specific tips, and interview preparation.',
 $j$[{"type":"paragraph","content":"Post-UTME screening is the final hurdle before university admission. Each institution designs its own exam format, making targeted preparation essential rather than generic JAMB-style revision."},{"type":"heading","content":"Common Post-UTME Formats"},{"type":"list","content":["CBT-based objective questions (UNILAG, UNN, ABU)","Written essay-type exams (OAU, UI)","Combined JAMB score + Post-UTME aggregate (most federal universities)","Interview-based screening for competitive programs (Medicine, Law, Engineering)"]},{"type":"heading","content":"Preparation Strategy"},{"type":"paragraph","content":"Obtain past Post-UTME questions from your target university. Focus on current affairs, your chosen subject area, and general knowledge. Practice time management, many Post-UTME exams are shorter than JAMB but equally dense."},{"type":"callout","content":"Important: Check your university official website for the exact format, duration, and syllabus. Formats change annually, relying on outdated information is the most common reason for poor performance."}]$j$::jsonb,
 'education', 'Examination Preparation', 'a2', '2024-12-10', 9, array['Post-UTME','Screening','University','Admission'], false, 'from-red-500 to-orange-500')
